// Redis ZSet 延迟队列核心代码
public void add(String taskId, long delayMillis) {
    long score = System.currentTimeMillis() + delayMillis;
    redis.zadd(DELAY_QUEUE, score, taskId);
}
public List<String> poll() {
    long now = System.currentTimeMillis();
    Set<String> tasks = redis.zrangeByScore(DELAY_QUEUE, 0, now);
    if (!tasks.isEmpty()) redis.zrem(DELAY_QUEUE, tasks.toArray());
    return new ArrayList<>(tasks);
}
